for cap in range(1,6):
  for t in range(300):
    c=LRUCache(cap); r=OrderedDict()
    for _ in range(50):
      k=random.randint(0,7)
      if random.random()<.5:
        a=c.get(k); b=None
        if k in r: r.move_to_end(k); b=r[k]
